    cin >> n >> l >> r;

    int minimum = 0, maximum = 0;
    int power = 1;

    for (int i = 0; i < l; ++i) {
        minimum += power;
        power *= 2;
    }
    minimum += n - l;

    power = 1;
    for (int i = 0; i < r; ++i) {
        maximum += power;
